import{crc32}from'./zip.js';import{validateMusicAsset,from64}from'./music-assets.js';import{encodeSprite4bpp,encodeSpritePalette,literalSpriteLZ,decodeSprite4bpp,decodeSpritePalette,decompressSpriteLZ}from'./native-sprites.js';import{sourceBytes,sourceText,sourcePath}from'./source-archive.js';
function join(parts){const out=new Uint8Array(parts.reduce((n,b)=>n+b.length,0));let at=0;for(const b of parts){out.set(b,at);at+=b.length;}return out;}
function chunk(tag,data){const out=new Uint8Array(data.length+12),v=new DataView(out.buffer);v.setUint32(0,data.length);out.set(sourceBytes(tag),4);out.set(data,8);v.setUint32(data.length+8,crc32(out.subarray(4,data.length+8)));return out;}
export function spritePNG(pixels,width,height,palette){encodeSprite4bpp(pixels,width,height);encodeSpritePalette(palette);const rows=new Uint8Array((width+1)*height);for(let y=0;y<height;y++)rows.set(pixels.slice(y*width,(y+1)*width),y*(width+1)+1);const z=[Uint8Array.of(0x78,1)];for(let at=0;at<rows.length;at+=65535){const p=rows.subarray(at,at+65535),n=p.length;z.push(Uint8Array.of(at+n===rows.length?1:0,n&255,n>>>8,(~n)&255,(~n>>>8)&255),p);}let a=1,b=0;for(const n of rows){a=(a+n)%65521;b=(b+a)%65521;}const adler=new Uint8Array(4);new DataView(adler.buffer).setUint32(0,(b*65536+a)>>>0);z.push(adler);const ihdr=new Uint8Array(13),v=new DataView(ihdr.buffer);v.setUint32(0,width);v.setUint32(4,height);ihdr.set([8,3,0,0,0],8);const pal=Uint8Array.from(palette.flatMap(c=>[1,3,5].map(i=>parseInt(c.slice(i,i+2),16))));return join([Uint8Array.of(137,80,78,71,13,10,26,10),chunk('IHDR',ihdr),chunk('PLTE',pal),chunk('tRNS',Uint8Array.of(0,...Array(15).fill(255))),chunk('IDAT',join(z)),chunk('IEND',new Uint8Array())]);}
export function pngSize(b){if(b.length<24||!b.subarray(0,8).every((n,i)=>n===[137,80,78,71,13,10,26,10][i]))throw Error('Invalid source PNG.');const v=new DataView(b.buffer,b.byteOffset,b.byteLength);return{width:v.getUint32(16),height:v.getUint32(20)};}
export function spriteSheet(g,role){const v=g?.views?.[role];if(!v?.frames?.length)throw Error('Sprite group has no '+role+' view.');return{width:v.width,height:v.height*v.frames.length,pixels:v.frames.flatMap(f=>Array.from(f))};}
export function sourceSpriteBytes(g,role,path,original,{shiny=false}={}){sourcePath(path);const pal=shiny?g.shiny:g.normal;if(/\.(pal|gbapal)(\.lz)?$/.test(path)){if(path.endsWith('.pal')){if(original&&!/^JASC-PAL\r?\n0100\r?\n16\r?\n/.test(sourceText(original)))throw Error('Replace only single 16-colour JASC palettes.');return sourceBytes('JASC-PAL\n0100\n16\n'+pal.map(c=>[1,3,5].map(i=>parseInt(c.slice(i,i+2),16)).join(' ')).join('\n')+'\n');}const bytes=encodeSpritePalette(pal),raw=path.endsWith('.lz')?decompressSpriteLZ(original,0):original;if(raw.length!==32)throw Error('Replace only single 16-colour palettes.');return path.endsWith('.lz')?literalSpriteLZ(bytes):bytes;}const sheet=spriteSheet(g,role);if(path.endsWith('.png')){const size=pngSize(original);if(size.width!==sheet.width||size.height!==sheet.height)throw Error('Source expects '+size.width+' × '+size.height+' pixels; selected view is '+sheet.width+' × '+sheet.height+'. Match its dimensions and frames first.');return spritePNG(sheet.pixels,sheet.width,sheet.height,pal);}if(!/\.4bpp(\.lz)?$/.test(path))throw Error('Choose PNG, 4bpp or a palette target.');const bytes=encodeSprite4bpp(sheet.pixels,sheet.width,sheet.height),raw=path.endsWith('.lz')?decompressSpriteLZ(original,0):original;if(bytes.length!==raw.length)throw Error('Source graphics size differs. Match original dimensions and frames.');return path.endsWith('.lz')?literalSpriteLZ(bytes):bytes;}
export function readRawSourceSprite(bytes,pal,{width,height,frames=1,compressed=false,paletteCompressed=false}={}){if(![width,height].every(n=>Number.isInteger(n)&&n>=8&&n<=128&&n%8===0)||!Number.isInteger(frames)||frames<1||frames>64)throw Error('Use 8–128 pixel dimensions and 1–64 frames.');const raw=compressed?decompressSpriteLZ(bytes,0):bytes,p=paletteCompressed?decompressSpriteLZ(pal,0):pal,size=width*height/2;if(raw.length!==size*frames||p.length!==32)throw Error('Source dimensions or palette size do not match.');return{width,height,frames:Array.from({length:frames},(_,i)=>Array.from(decodeSprite4bpp(raw.subarray(i*size,(i+1)*size),width,height))),palette:decodeSpritePalette(p)};}
export function musicAssembly(asset,symbol){if(!/^[A-Za-z_]\w*$/.test(symbol))throw Error('Invalid song symbol.');validateMusicAsset(asset);const b=from64(asset.bytes),v=new DataView(b.buffer),ptrs=new Set(asset.pointers),offsets=new Set([asset.header,...asset.pointers,...asset.pointers.map(at=>v.getUint32(at,true))]),label=n=>n===asset.header?symbol:'.L'+symbol+'_'+n,lines=['@ Portable MP2K song with referenced instruments and samples.','.section .rodata','.balign 4','.global '+symbol,'.type '+symbol+', %object'];for(let at=0;at<b.length;){if(offsets.has(at))lines.push(label(at)+':');if(ptrs.has(at)){lines.push(' .4byte '+label(v.getUint32(at,true)));at+=4;}else{const start=at;at++;while(at<b.length&&at-start<16&&!offsets.has(at))at++;lines.push(' .byte '+Array.from(b.subarray(start,at),n=>'0x'+n.toString(16).padStart(2,'0')).join(', '));}}return lines.join('\n')+'\n';}
export function sourceSongSlots(files,engine){if(['cfru','shiny'].includes(engine)){const text=sourceText(files.get('include/constants/songs.h')||new Uint8Array()),seen=new Set(),rows=[];for(const m of text.matchAll(/^\s*#define\s+((?:MUS|BGM)_\w+)\s+(0x[\da-fA-F]+|\d+)\b/gm)){const id=Number(m[2]);if(id>=0&&id<65536&&!seen.has(id)){seen.add(id);rows.push({id:String(id),symbol:m[1],label:m[1]+' · '+id});}}return rows;}const path=['sound/song_table.inc','sound/song_table.s'].find(p=>files.has(p));if(!path)return[];const rows=[];sourceText(files.get(path)).split('\n').forEach((line,i)=>{const m=line.match(/^\s*song\s+(\w+)\s*,/);if(m&&/^(mus_|song_)/.test(m[1])&&!/dummy/.test(m[1]))rows.push({id:path+':'+i,path,line:i,symbol:m[1],label:m[1]});});return rows;}
export function installSourceMusic(files,engine,track,slotId,index=0,{songLimit}={}){const slot=sourceSongSlots(files,engine).find(s=>s.id===slotId),cfru=['cfru','shiny'].includes(engine);if(!slot)throw Error('Choose an existing source song slot.');if(cfru&&(!Number.isInteger(songLimit)||Number(slotId)>=songLimit))throw Error('Reopen the target ROM to verify this song slot. CFRU source export does not expand song tables.');let number=index,symbol,path;do{symbol='mus_studio_'+number++;path=(cfru?'assembly/':'sound/songs/')+symbol+'.s';}while(files.has(path));const out=new Map(files);out.set(path,sourceBytes(musicAssembly(track.asset,symbol)));if(cfru){if(!files.has('songs'))throw Error('CFRU songs insertion list missing.');const lines=sourceText(files.get('songs')).split('\n'),matches=[];let depth=0;lines.forEach((line,i)=>{if(/^\s*#\s*if/.test(line))depth++;if(/^\s*#\s*endif/.test(line))depth--;const m=line.match(/^\s*(0x[\da-fA-F]+|\d+)\s+(\S+)/);if(m&&Number(m[1])===Number(slotId))matches.push({i,depth});});if(matches.length>1||matches.some(m=>m.depth))throw Error('Conditional or duplicate song insertion rows; edit source first.');if(matches.length)lines[matches[0].i]=slotId+' '+symbol;else lines.push(slotId+' '+symbol);out.set('songs',sourceBytes(lines.join('\n')));}else{const lines=sourceText(files.get(slot.path)).split('\n');lines[slot.line]=lines[slot.line].replace(/(\bsong\s+)\w+/,(_,head)=>head+symbol);out.set(slot.path,sourceBytes(lines.join('\n')));}return{files:out,path,symbol,slot};}
